m add host name WAN_IP ip-address 198.51.100.2 ignore-warnings true
m add host name WEB_SRV ip-address 10.30.0.10 ignore-warnings true
m add host name MAIL_SRV ip-address 10.30.0.25 ignore-warnings true
m add address-range name ADMIN_PCS ip-address-first 10.10.0.50 ip-address-last 10.10.0.59 ignore-warnings true
m add network name PARTNER_NET subnet 203.0.113.0 mask-length 25 ignore-warnings true
